// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool ok;
        try c.endConfiguration() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.configured(), "endConfiguration must set configured == true");
        } else {
            assertTrue(c.configured(), "endConfiguration must set configured == true even if call reverted");
        }
    }
}
